"""Independently score the registered bandit from archived actions and holdout rows."""
import itertools
import json
import math
import statistics
import sys
from pathlib import Path


def score(trajectory):
    assert [row["step"] for row in trajectory["steps"]] == list(range(1, 97))
    assert set(trajectory["eval"]) == {"0", "32", "64", "96"}
    scores = {}
    for checkpoint, row in trajectory["eval"].items():
        assert len(row["gold_logp_rows"]) == len(row["greedy_match_rows"]) == row["examples"] == 512
        p = statistics.mean(math.exp(logp) for logp in row["gold_logp_rows"])
        assert abs(row["expected_reward"] - p) <= 1e-7
        assert abs(row["gold_nll"] + statistics.mean(row["gold_logp_rows"])) <= 1e-6
        assert row["greedy_hits"] == sum(row["greedy_match_rows"])
        scores[checkpoint] = p
    return scores


def audit_steps(steps, arm):
    mixed = positive_actions = changed_groups = active_writes = 0
    largest_norm = 0.0
    for step in steps:
        assert all(math.isfinite(step[key]) for key in ("loss", "gradient_norm"))
        credited = 0
        if arm == "off":
            assert step["write_advantages"] is None and step["credit"] is None
        else:
            assert len(step["write_advantages"]) == 4
        assert len(step["gold"]) == len(step["actions"]) == len(step["rewards"]) == 4
        for index, (gold, actions) in enumerate(zip(step["gold"], step["actions"], strict=True)):
            assert len(actions) == 4
            rewards = [int(action == gold) for action in actions]
            assert rewards == step["rewards"][index]
            positive_actions += sum(rewards)
            mixed += 0 < sum(rewards) < 4
            correct = [reward - sum(rewards) / 4 for reward in rewards]
            assert correct == step["gradient_advantages"][index] and sum(correct) == 0
            if arm == "off":
                continue
            applied = step["write_advantages"][index]
            if arm == "aligned":
                assert applied == correct
            else:
                assert sorted(applied) == sorted(correct)
            changed_groups += applied != correct
            credited += sum(advantage != 0 for advantage in applied)
        if arm != "off":
            credit = step["credit"]
            norm = credit["max_update_norm"]
            assert credit["local_rollouts"] == 16 and credit["local_credited_rollouts"] == credited
            assert math.isfinite(norm) and 0 <= norm <= 0.03 + 1e-7
            if credited == 0:
                assert norm == 0
            else:
                assert norm > 0
            largest_norm = max(largest_norm, norm)
            active_writes += norm > 0
    assert mixed > 0
    return {"mixed_groups": mixed, "positive_sampled_actions": positive_actions,
            "nonzero_update_steps": active_writes, "changed_shuffle_groups": changed_groups,
            "largest_update_norm": largest_norm}


def compare(summaries, control):
    differences = {}
    for seed, arms in summaries.items():
        treatment, comparison = (arms[arm]["expected_reward"] for arm in ("aligned", control))
        differences[seed] = statistics.mean(treatment[str(step)] - comparison[str(step)] for step in (32, 64, 96))
    deltas = list(differences.values())
    total = math.fsum(deltas)
    null = [math.fsum(sign * delta for sign, delta in zip(signs, deltas, strict=True))
            for signs in itertools.product((-1, 1), repeat=len(deltas))]
    tail = sum(draw >= total - 1e-12 for draw in null)
    p = tail / len(null)
    effect = total / len(deltas)
    wins = sum(delta > 0 for delta in deltas)
    return {"paired_delta": differences, "effect": effect, "positive_seeds": wins, "exact_p": p,
            "tail_count": tail, "sign_configurations": len(null), "passed": effect >= 0.01 and wins >= 6 and p <= 0.025}


def main(original, replay, output):
    assert list(replay) == list(original) == [str(seed) for seed in range(70521, 77522, 1000)]
    stats = {}
    for seed, arm_runs in replay.items():
        assert set(arm_runs) == {"off", "aligned", "shuffled"}
        assert len({arm["initial_hash"] for arm in arm_runs.values()}) == 1
        initial = [arm["eval"]["0"] for arm in arm_runs.values()]
        assert all(value == initial[0] for value in initial)
        stats[seed] = {}
        for arm, trajectory in arm_runs.items():
            scores = score(trajectory)
            step_stats = audit_steps(trajectory["steps"], arm)
            for row in trajectory["eval"].values():
                row.pop("gold_logp_rows")
                row.pop("greedy_match_rows")
            assert trajectory == original[seed][arm]
            stats[seed][arm] = {"initial_hash": trajectory["initial_hash"],
                                "final_hash": trajectory["final_hash"], "expected_reward": scores, **step_stats}
    competence = sum(seed["off"]["expected_reward"]["0"] > 0.10 for seed in stats.values())
    comparisons = {arm: compare(stats, arm) for arm in ("off", "shuffled")}
    result = {"rows_audited": 8 * 3 * 4 * 512, "train_actions_audited": 8 * 3 * 96 * 16,
              "exact_numeric_replays": 24, "competent_initializations": competence,
              "comparisons": comparisons, "seed_results": stats,
              "advance": competence >= 6 and all(row["passed"] for row in comparisons.values())}
    output.write_text(json.dumps(result, indent=2, sort_keys=True, allow_nan=False) + "\n")


if __name__ == "__main__":
    main(*(json.loads(Path(name).read_text()) for name in sys.argv[1:3]), Path(sys.argv[3]))
